// ============================================================
// 丝柯克（Skirk）动态皮肤插件 · 客户端（独立版）
// ------------------------------------------------------------
// 任何 DeepSeek Harness 用户均可直接使用，零配置：
//   cordis_define → 新建插件（idPrefix 如 "skirk"），
//                   把本文件全部内容粘贴到 code.client；
//   cordis_run   → 在授权卡片上确认即可。
// 素材（640px 网页图 + 中文大招语音「沉于渊海。」）已内嵌为
// base64 数据 URI，不依赖任何本地文件。
// 可选全画质模式：配合同目录 host.js 使用（自动检测并切换到
// 原图素材，需在 host.js 中把 ASSET_DIR 改成素材文件夹路径）。
// ============================================================
const SKIN_DATA_URI = 'data:image/jpeg;base64,'
const BURST_DATA_URI = 'data:audio/ogg;base64,'

const CSS = `
.skirk-root { position: fixed; z-index: 99990; pointer-events: auto; user-select: none; -webkit-user-select: none; touch-action: none; }
.skirk-card { position: relative; width: 320px; height: 320px; cursor: pointer; border-radius: 30px; }
.skirk-img { display: block; width: 320px; height: 320px; object-fit: cover; border-radius: 30px;
  border: 1px solid rgba(150, 200, 255, .45); background: #0a1322;
  box-shadow: 0 14px 48px rgba(0, 0, 0, .5), 0 0 0 1px rgba(120, 190, 255, .12) inset;
  animation: skirk-bob 3.6s ease-in-out infinite; }
.skirk-card:hover .skirk-img { box-shadow: 0 14px 54px rgba(90, 160, 255, .5), 0 0 30px rgba(110, 190, 255, .35); }
@keyframes skirk-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-7px); } }
.skirk-is-bursting .skirk-img { animation: skirk-shake .55s ease-in-out; }
@keyframes skirk-shake {
  0% { transform: translate(0, 0) rotate(0deg); }
  15% { transform: translate(-12px, 4px) rotate(-2.5deg); }
  30% { transform: translate(12px, -5px) rotate(2.5deg); }
  45% { transform: translate(-10px, 3px) rotate(-1.8deg); }
  60% { transform: translate(9px, -3px) rotate(1.8deg); }
  80% { transform: translate(-4px, 0) rotate(-.6deg); }
  100% { transform: translate(0, 0) rotate(0deg); }
}
.skirk-burst { position: absolute; inset: 0; border-radius: 30px; pointer-events: none; overflow: visible; }
.skirk-flash { position: absolute; inset: 0; border-radius: 30px;
  background: radial-gradient(circle at 50% 40%, rgba(190, 235, 255, .95), rgba(90, 140, 255, .5) 45%, rgba(30, 60, 140, .15) 75%, transparent 100%);
  animation: skirk-flash .6s ease-out forwards; }
@keyframes skirk-flash { 0% { opacity: 0; } 12% { opacity: 1; } 100% { opacity: 0; } }
.skirk-shock { position: absolute; left: 50%; top: 50%; width: 230px; height: 230px; margin: -115px 0 0 -115px; border-radius: 50%;
  border: 5px solid rgba(160, 220, 255, .9); animation: skirk-shock .7s cubic-bezier(.1, .7, .3, 1) forwards; }
@keyframes skirk-shock { 0% { transform: scale(.2); opacity: .95; } 100% { transform: scale(2.1); opacity: 0; } }
.skirk-slash { position: absolute; height: 5px; border-radius: 4px; opacity: 0;
  background: linear-gradient(90deg, transparent, rgba(230, 248, 255, .95) 30%, rgba(160, 220, 255, .9) 60%, transparent);
  filter: drop-shadow(0 0 10px rgba(150, 210, 255, .9)); }
.skirk-slash-1 { left: -30%; top: 30%; width: 160%; transform: rotate(-14deg); animation: skirk-slash-a .55s ease-out .05s forwards; }
.skirk-slash-2 { left: -30%; top: 62%; width: 160%; transform: rotate(9deg); animation: skirk-slash-b .55s ease-out .12s forwards; }
.skirk-slash-3 { left: 10%; top: -20%; width: 5px; height: 140%; transform: rotate(18deg); animation: skirk-slash-c .6s ease-out .18s forwards; }
@keyframes skirk-slash-a { 0% { opacity: 0; transform: translateX(0) rotate(-14deg) scaleX(.4); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateX(170px) rotate(-14deg) scaleX(1.1); } }
@keyframes skirk-slash-b { 0% { opacity: 0; transform: translateX(0) rotate(9deg) scaleX(.4); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateX(-170px) rotate(9deg) scaleX(1.1); } }
@keyframes skirk-slash-c { 0% { opacity: 0; transform: translateY(80px) rotate(18deg) scaleY(.3); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateY(-150px) rotate(18deg) scaleY(1.2); } }
.skirk-shards { position: absolute; inset: 0; }
.skirk-shard { position: absolute; left: 50%; top: 50%; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 2px;
  background: linear-gradient(135deg, #e8fbff, #9fd8ff 60%, #5f8cff);
  box-shadow: 0 0 12px rgba(150, 215, 255, .95); opacity: 0;
  animation: skirk-shard-fly .8s ease-out forwards; }
@keyframes skirk-shard-fly {
  0% { opacity: 0; transform: translate(0, 0) scale(.4); }
  12% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(1.15) rotate(220deg); }
}
.skirk-skill { position: absolute; left: 0; right: 0; top: -48px; text-align: center; white-space: nowrap;
  color: #cfe9ff; font: 700 19px/1 'Microsoft YaHei', sans-serif; text-shadow: 0 0 14px rgba(120, 190, 255, .95), 0 1px 2px #000;
  animation: skirk-text .95s ease-out forwards; }
.skirk-line { position: absolute; left: 0; right: 0; bottom: -58px; text-align: center; white-space: nowrap;
  color: #eef7ff; font: 700 24px/1 'Microsoft YaHei', sans-serif; letter-spacing: 4px; text-shadow: 0 0 16px rgba(140, 205, 255, .95), 0 1px 3px #000;
  animation: skirk-line-in 1.9s ease-out forwards; }
@keyframes skirk-text { 0% { opacity: 0; transform: translateY(8px); } 20% { opacity: 1; transform: translateY(0); } 70% { opacity: 1; } 100% { opacity: 0; transform: translateY(-6px); } }
@keyframes skirk-line-in { 0% { opacity: 0; transform: scale(.85); } 12% { opacity: 1; transform: scale(1); } 80% { opacity: 1; } 100% { opacity: 0; } }
.skirk-close { position: absolute; right: -12px; top: -12px; width: 30px; height: 30px; border: none; border-radius: 50%;
  background: rgba(10, 20, 36, .85); color: #bfe0ff; font: 700 17px/30px sans-serif; cursor: pointer; padding: 0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, .5); }
.skirk-close:hover { background: rgba(40, 80, 160, .9); color: #fff; }
.skirk-warn { position: absolute; left: -12px; top: -12px; width: 26px; height: 26px; border-radius: 50%; background: #b3402e; color: #fff; text-align: center; font: 700 14px/26px sans-serif; box-shadow: 0 2px 8px rgba(0, 0, 0, .5); }
.skirk-pill { position: fixed; z-index: 99990; pointer-events: auto; border: 1px solid rgba(150, 200, 255, .55); border-radius: 999px; padding: 10px 22px;
  background: rgba(12, 22, 40, .9); color: #d6ecff; font: 700 16px/1.4 'Microsoft YaHei', sans-serif; cursor: pointer; user-select: none;
  box-shadow: 0 6px 18px rgba(0, 0, 0, .5); }
.skirk-pill:hover { background: rgba(30, 60, 120, .95); }
`

return {
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return
    ctx.effect(() => styles.insert(CSS))
    const VOICE_TEXT = '沉于渊海。'
    const SKILL_TEXT = '元素爆发 · 极恶技·灭'
    const PARTICLE_COUNT = 18

    function SkirkWidget() {
      // 素材地址：默认内嵌 data URI（零配置可用）；若加载了 host.js 全画质模式，自动切换为路由地址。
      const [assets, setAssets] = React.useState({ skin: SKIN_DATA_URI, burst: BURST_DATA_URI })
      const [imgFailed, setImgFailed] = React.useState(false)
      const [bursting, setBursting] = React.useState(false)
      const [burstKey, setBurstKey] = React.useState(0)
      const [hidden, setHidden] = React.useState(false)
      const [pos, setPos] = React.useState(() => ({
        x: Math.max(8, window.innerWidth - 400),
        y: Math.max(8, window.innerHeight - 540),
      }))
      const posRef = React.useRef(pos)
      posRef.current = pos
      const audioRef = React.useRef(null)
      const movedRef = React.useRef(false)

      React.useEffect(() => {
        host.call('skirk-urls', null).then((r) => {
          if (r && typeof r.skin === 'string' && typeof r.burst === 'string') {
            setAssets({ skin: window.location.origin + r.skin, burst: window.location.origin + r.burst })
          }
        }).catch(() => {})
      }, [])

      React.useEffect(() => () => {
        if (audioRef.current) { try { audioRef.current.pause() } catch (e) {} }
      }, [])

      const triggerBurst = () => {
        setBurstKey((k) => k + 1)
        setBursting(true)
        try {
          if (audioRef.current) { try { audioRef.current.pause() } catch (e) {} }
          const audio = new Audio(assets.burst)
          audioRef.current = audio
          const playing = audio.play()
          if (playing !== undefined && playing.catch) playing.catch((err) => console.warn('skirk-skin: voice play failed', err))
        } catch (err) {
          console.error('skirk-skin: audio failed', err)
        }
      }

      const onPointerDown = (e) => {
        if (e.pointerType === 'mouse' && e.button !== 0) return
        movedRef.current = false
        const startX = e.clientX
        const startY = e.clientY
        const startPos = posRef.current
        const move = (ev) => {
          const dx = ev.clientX - startX
          const dy = ev.clientY - startY
          if (Math.abs(dx) + Math.abs(dy) > 6) movedRef.current = true
          setPos({
            x: Math.max(-180, Math.min(window.innerWidth - 90, startPos.x + dx)),
            y: Math.max(-180, Math.min(window.innerHeight - 90, startPos.y + dy)),
          })
        }
        const up = () => {
          window.removeEventListener('pointermove', move)
          window.removeEventListener('pointerup', up)
        }
        window.addEventListener('pointermove', move)
        window.addEventListener('pointerup', up)
      }

      if (hidden) {
        return React.createElement('button', {
          className: 'skirk-pill',
          style: { left: pos.x, top: pos.y },
          onPointerDown: onPointerDown,
          onClick: () => setHidden(false),
          title: '显示丝柯克皮肤',
        }, '丝柯克 ✦')
      }

      const burstLayer = bursting
        ? React.createElement('div', { className: 'skirk-burst', key: 'burst-' + burstKey },
            React.createElement('div', { className: 'skirk-flash' }),
            React.createElement('div', { className: 'skirk-shock' }),
            React.createElement('div', { className: 'skirk-slash skirk-slash-1' }),
            React.createElement('div', { className: 'skirk-slash skirk-slash-2' }),
            React.createElement('div', { className: 'skirk-slash skirk-slash-3' }),
            React.createElement('div', { className: 'skirk-shards' },
              Array.from({ length: PARTICLE_COUNT }, (_, i) => React.createElement('span', {
                key: i,
                className: 'skirk-shard',
                style: {
                  '--dx': ((i % 5) - 2) * 100 + ((i * 13) % 19) - 9 + 'px',
                  '--dy': ((Math.floor(i / 5) % 3) - 1) * 118 - 70 + 'px',
                  animationDelay: (i % 4) * 0.03 + 's',
                },
              }))),
            React.createElement('div', { className: 'skirk-skill' }, SKILL_TEXT),
            React.createElement('div', { className: 'skirk-line', onAnimationEnd: () => setBursting(false) }, '“' + VOICE_TEXT + '”'),
          )
        : null

      return React.createElement('div', {
        className: 'skirk-root',
        style: { left: pos.x, top: pos.y },
        onPointerDown: onPointerDown,
      },
        React.createElement('div', {
          className: 'skirk-card' + (bursting ? ' skirk-is-bursting' : ''),
          onClick: () => { if (!movedRef.current) triggerBurst() },
          title: '点击：释放元素爆发「极恶技·灭」',
        },
          React.createElement('img', {
            className: 'skirk-img',
            src: assets.skin,
            draggable: false,
            alt: '丝柯克',
            onError: () => setImgFailed(true),
          }),
          burstLayer,
          imgFailed
            ? React.createElement('div', { className: 'skirk-warn', title: '图片素材加载失败' }, '⚠')
            : null,
          React.createElement('button', {
            className: 'skirk-close',
            title: '收起皮肤',
            onClick: (e) => { e.stopPropagation(); setHidden(true) },
          }, '×'),
        ))
    }

    slots.inject('shell.overlay', () => slots.register(
      { name: 'shell.overlay', id: 'skirk-skin-widget', order: 100, label: '丝柯克动态皮肤' },
      () => React.createElement(SkirkWidget),
    ))
  },
}
